package com.lms.assessmentservice.runtime;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Domain kernel for "Grading and grade publication" (generated by gherkin-ai).
 * Pure domain logic: no framework, no I/O. Extend the command handlers with your business rules.
 */
public class GradeAggregate {
    private final String id;
    private GradeState state = GradeState.PENDING;
    private long version;
    private final List<GradeDomainEvent> pendingEvents = new ArrayList<>();

    public GradeAggregate(String id) {
        if (id == null || id.isBlank()) throw new DomainValidationException("Grade id is required");
        this.id = id;
    }

    /** Rebuilds an aggregate from persisted state; no events are recorded. */
    public static GradeAggregate restore(String id, GradeState state, long version) {
        var aggregate = new GradeAggregate(id);
        aggregate.state = state;
        aggregate.version = version;
        return aggregate;
    }

    public String getId() { return id; }
    public GradeState getState() { return state; }
    public long getVersion() { return version; }

    /** Events recorded since the aggregate was loaded (to be saved via the outbox). */
    public List<GradeDomainEvent> getPendingEvents() { return Collections.unmodifiableList(pendingEvents); }

    public GradeDomainEvent publishGrade(GradeCommand command) {
        assertValid(command);
        return record(GradeEventType.SubmissionGraded, command.payload());
    }

    private void assertValid(GradeCommand command) {
        if (command == null || command.id() == null || command.id().isBlank()) throw new DomainValidationException("Command id is required");
        if (!command.id().equals(id)) throw new DomainValidationException("Command targets " + command.id() + ", not " + id);
    }

    private GradeDomainEvent record(GradeEventType type, Map<String, Object> payload) {
        version += 1;
        var event = new GradeDomainEvent(type, id, version, Instant.now(), payload == null ? Map.of() : payload);
        pendingEvents.add(event);
        return event;
    }
}
